/**
 * Utilidades de criptografía usando Web Crypto API.
 * No requiere librerías externas.
 */

const ALGO_PBKDF2 = 'PBKDF2';
const ALGO_AES = 'AES-GCM';

/**
 * Genera una sal aleatoria
 */
export const generateSalt = (): string => {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return btoa(String.fromCharCode(...salt));
};

/**
 * Deriva una clave a partir de un PIN y una sal
 */
async function deriveKey(pin: string, saltStr: string): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const salt = Uint8Array.from(atob(saltStr), c => c.charCodeAt(0));
  const baseKey = await crypto.subtle.importKey(
    'raw',
    encoder.encode(pin),
    ALGO_PBKDF2,
    false,
    ['deriveKey']
  );

  return crypto.subtle.deriveKey(
    {
      name: ALGO_PBKDF2,
      salt: salt,
      iterations: 100000,
      hash: 'SHA-256',
    },
    baseKey,
    { name: ALGO_AES, length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

/**
 * Encripta un texto
 */
export async function encryptText(text: string, pin: string, salt: string): Promise<string> {
  const key = await deriveKey(pin, salt);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encoded = new TextEncoder().encode(text);

  const encrypted = await crypto.subtle.encrypt(
    { name: ALGO_AES, iv },
    key,
    encoded
  );

  const combined = new Uint8Array(iv.length + encrypted.byteLength);
  combined.set(iv);
  combined.set(new Uint8Array(encrypted), iv.length);

  return btoa(String.fromCharCode(...combined));
}

/**
 * Desencripta un texto
 */
export async function decryptText(encryptedBase64: string, pin: string, salt: string): Promise<string> {
  try {
    const key = await deriveKey(pin, salt);
    const combined = Uint8Array.from(atob(encryptedBase64), c => c.charCodeAt(0));
    const iv = combined.slice(0, 12);
    const data = combined.slice(12);

    const decrypted = await crypto.subtle.decrypt(
      { name: ALGO_AES, iv },
      key,
      data
    );

    return new TextDecoder().decode(decrypted);
  } catch (e) {
    throw new Error('PIN incorrecto o datos corruptos');
  }
}

/**
 * Hashea el PIN para verificación local (no para desencriptar)
 */
export async function hashPin(pin: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(pin + 'pepper_local_v1');
  const hash = await crypto.subtle.digest('SHA-256', data);
  return btoa(String.fromCharCode(...new Uint8Array(hash)));
}

import Dexie, { Table } from 'dexie';
import { Note, Document, ShoppingItem, Appointment } from '../domain/types';

export class BovedaDB extends Dexie {
  notes!: Table<Note>;
  documents!: Table<Document>;
  shoppingList!: Table<ShoppingItem>;
  appointments!: Table<Appointment>;

  constructor() {
    super('BovedaPersonalDB');
    this.version(1).stores({
      notes: 'id, title, isFavorite, createdAt',
      documents: 'id, name, category, createdAt',
      shoppingList: 'id, completed, createdAt',
      appointments: 'id, date, createdAt'
    });
  }
}

export const db = new BovedaDB();

/**
 * Repositorios encapsulados para lógica de negocio
 */
export const NoteRepository = {
  getAll: () => db.notes.orderBy('createdAt').reverse().toArray(),
  add: (note: Note) => db.notes.add(note),
  update: (id: string, changes: Partial<Note>) => db.notes.update(id, changes),
  delete: (id: string) => db.notes.delete(id),
  toggleFavorite: async (id: string) => {
    const note = await db.notes.get(id);
    if (note) return db.notes.update(id, { isFavorite: !note.isFavorite });
  }
};

export const ShoppingRepository = {
  getAll: () => db.shoppingList.orderBy('createdAt').toArray(),
  add: (item: ShoppingItem) => db.shoppingList.add(item),
  toggle: async (id: string) => {
    const item = await db.shoppingList.get(id);
    if (item) return db.shoppingList.update(id, { completed: !item.completed });
  },
  delete: (id: string) => db.shoppingList.delete(id)
};

export const AppointmentRepository = {
  getAll: () => db.appointments.orderBy('date').toArray(),
  add: (app: Appointment) => db.appointments.add(app),
  delete: (id: string) => db.appointments.delete(id)
};

export const DocumentRepository = {
  getAll: () => db.documents.orderBy('createdAt').reverse().toArray(),
  add: (doc: Document) => db.documents.add(doc),
  delete: (id: string) => db.documents.delete(id)
};

import { create } from 'zustand';
import { AppSettings, AuthState } from '../domain/types';

interface GlobalState {
  settings: AppSettings;
  auth: AuthState;

  setSeniorMode: (enabled: boolean) => void;
  setEncryption: (enabled: boolean) => void;
  setReadOnly: (enabled: boolean) => void;

  lock: () => void;
  unlock: () => void;
  setupPin: (hash: string, salt: string) => void;
}

// Cargar ajustes desde LocalStorage por simplicidad en configuración
const getInitialSettings = (): AppSettings => {
  const saved = localStorage.getItem('boveda_settings');
  return saved ? JSON.parse(saved) : {
    seniorMode: false,
    readOnly: false,
    encryptionEnabled: true,
    autoLockMinutes: 5
  };
};

const getInitialAuth = (): AuthState => {
  const hash = localStorage.getItem('boveda_pin_hash');
  const salt = localStorage.getItem('boveda_salt');
  return {
    isLocked: !!hash,
    pinHash: hash || undefined,
    salt: salt || undefined
  };
};

export const useStore = create<GlobalState>((set) => ({
  settings: getInitialSettings(),
  auth: getInitialAuth(),

  setSeniorMode: (seniorMode) => set((state) => {
    const newSettings = { ...state.settings, seniorMode };
    localStorage.setItem('boveda_settings', JSON.stringify(newSettings));
    return { settings: newSettings };
  }),

  setEncryption: (encryptionEnabled) => set((state) => {
    const newSettings = { ...state.settings, encryptionEnabled };
    localStorage.setItem('boveda_settings', JSON.stringify(newSettings));
    return { settings: newSettings };
  }),

  setReadOnly: (readOnly) => set((state) => {
    const newSettings = { ...state.settings, readOnly };
    localStorage.setItem('boveda_settings', JSON.stringify(newSettings));
    return { settings: newSettings };
  }),

  lock: () => set((state) => ({ auth: { ...state.auth, isLocked: true } })),

  unlock: () => set((state) => ({ auth: { ...state.auth, isLocked: false } })),

  setupPin: (hash, salt) => {
    localStorage.setItem('boveda_pin_hash', hash);
    localStorage.setItem('boveda_salt', salt);
    set((state) => ({ 
      auth: { ...state.auth, pinHash: hash, salt, isLocked: false } 
    }));
  }
}));

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}) => {
  const baseStyles = 'inline-flex items-center justify-center rounded-lg font-medium transition-all active:scale-95 disabled:opacity-50 disabled:active:scale-100';

  const variants = {
    primary: 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-900/20',
    secondary: 'bg-dark-border text-gray-200 hover:bg-gray-800',
    danger: 'bg-red-600 text-white hover:bg-red-700',
    ghost: 'bg-transparent hover:bg-white/5 text-gray-400 hover:text-white'
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-xs',
    md: 'px-4 py-2 text-sm',
    lg: 'px-6 py-3 text-base'
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

