import { useState, useCallback } from 'react';
import { decryptText, encryptText } from '../../shared/crypto';
import { useStore } from '../store';

/**
 * Hook para gestionar operaciones criptográficas con el PIN de sesión
 */
export const useCrypto = () => {
  const [sessionPin, setSessionPin] = useState<string | null>(null);
  const { auth } = useStore();

  const encrypt = useCallback(async (text: string) => {
    if (!sessionPin || !auth.salt) throw new Error('Sesión no autorizada');
    return encryptText(text, sessionPin, auth.salt);
  }, [sessionPin, auth.salt]);

  const decrypt = useCallback(async (encrypted: string) => {
    if (!sessionPin || !auth.salt) throw new Error('Sesión no autorizada');
    return decryptText(encrypted, sessionPin, auth.salt);
  }, [sessionPin, auth.salt]);

  return { setSessionPin, encrypt, decrypt, hasSession: !!sessionPin };
};

import React, { useState, useEffect } from 'react';
import { NoteRepository } from '../../infra/db';
import { Note } from '../../domain/types';
import { Button, Card, Input, Modal } from '../../shared/ui';

export const NotesPage: React.FC = () => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [newNote, setNewNote] = useState({ title: '', content: '' });

  const loadNotes = async () => {
    const all = await NoteRepository.getAll();
    setNotes(all);
  };

  useEffect(() => {
    loadNotes();
  }, []);

  const handleSave = async () => {
    if (!newNote.title.trim()) return;
    await NoteRepository.add({
      id: crypto.randomUUID(),
      title: newNote.title,
      content: newNote.content,
      tags: [],
      isFavorite: false,
      isEncrypted: false,
      createdAt: Date.now(),
      updatedAt: Date.now()
    });
    setNewNote({ title: '', content: '' });
    setIsModalOpen(false);
    loadNotes();
  };

  const handleDelete = async (id: string) => {
    if (confirm('¿Eliminar esta nota?')) {
      await NoteRepository.delete(id);
      loadNotes();
    }
  };

  const filtered = notes.filter(n => 
    n.title.toLowerCase().includes(search.toLowerCase()) || 
    n.content.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-white">Notas Privadas</h2>
        <div className="flex gap-2">
          <Input 
            placeholder="Buscar notas..." 
            value={search} 
            onChange={(e) => setSearch(e.target.value)}
            className="md:w-64"
          />
          <Button onClick={() => setIsModalOpen(true)}>Nueva Nota</Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filtered.map(note => (
          <Card key={note.id} className="group flex flex-col h-full">
            <div className="flex justify-between items-start mb-2">
              <h3 className="font-semibold text-lg text-white">{note.title}</h3>
              <button 
                onClick={() => handleDelete(note.id)}
                className="opacity-0 group-hover:opacity-100 text-gray-500 hover:text-red-500 transition-opacity"
              >
                &times;
              </button>
            </div>
            <p className="text-gray-400 text-sm line-clamp-3 mb-4 flex-grow">{note.content}</p>
            <div className="text-xs text-gray-600">
              {new Date(note.createdAt).toLocaleDateString()}
            </div>
          </Card>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="text-center py-20 text-gray-500">
          No hay notas guardadas.
        </div>
      )}

      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title="Crear Nueva Nota"
      >
        <div className="space-y-4">
          <Input 
            placeholder="Título" 
            value={newNote.title}
            onChange={e => setNewNote({...newNote, title: e.target.value})}
          />
          <textarea 
            className="w-full h-40 bg-dark-surface border border-dark-border rounded-lg px-4 py-2 text-gray-100 focus:outline-none focus:border-blue-500 transition-colors"
            placeholder="Contenido de la nota..."
            value={newNote.content}
            onChange={e => setNewNote({...newNote, content: e.target.value})}
          />
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setIsModalOpen(false)}>Cancelar</Button>
            <Button onClick={handleSave}>Guardar Nota</Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ShoppingRepository } from '../../infra/db';
import { ShoppingItem } from '../../domain/types';
import { Button, Card, Input } from '../../shared/ui';

export const ShoppingPage: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [newItem, setNewItem] = useState('');

  const load = async () => {
    setItems(await ShoppingRepository.getAll());
  };

  useEffect(() => { load(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.trim()) return;
    await ShoppingRepository.add({
      id: crypto.randomUUID(),
      text: newItem,
      completed: false,
      createdAt: Date.now()
    });
    setNewItem('');
    load();
  };

  const handleToggle = async (id: string) => {
    await ShoppingRepository.toggle(id);
    load();
  };

  const handleDelete = async (id: string) => {
    await ShoppingRepository.delete(id);
    load();
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <h2 className="text-2xl font-bold text-white">Lista de Compras</h2>

      <form onSubmit={handleAdd} className="flex gap-2">
        <Input 
          placeholder="¿Qué necesitas comprar?" 
          value={newItem}
          onChange={e => setNewItem(e.target.value)}
        />
        <Button type="submit">Añadir</Button>
      </form>

      <div className="space-y-2">
        {items.map(item => (
          <Card key={item.id} className="flex items-center justify-between py-3">
            <div className="flex items-center gap-3">
              <input 
                type="checkbox" 
                checked={item.completed}
                onChange={() => handleToggle(item.id)}
                className="w-5 h-5 rounded border-dark-border text-blue-600 bg-dark-surface"
              />
              <span className={`${item.completed ? 'line-through text-gray-600' : 'text-gray-200'}`}>
                {item.text}
              </span>
            </div>
            <button 
              onClick={() => handleDelete(item.id)}
              className="text-gray-500 hover:text-red-500"
            >
              &times;
            </button>
          </Card>
        ))}
      </div>

      {items.length === 0 && (
        <p className="text-center text-gray-600 py-10">La lista está vacía.</p>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { hashPin, generateSalt } from '../../shared/crypto';
import { Button, Input, Card } from '../../shared/ui';

export const LoginPage: React.FC = () => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const { auth, unlock, setupPin } = useStore();

  const isSetup = !!auth.pinHash;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isSetup) {
      const hashed = await hashPin(pin);
      if (hashed === auth.pinHash) {
        unlock();
      } else {
        setError('PIN Incorrecto');
        setPin('');
      }
    } else {
      if (pin.length < 4) {
        setError('El PIN debe tener al menos 4 dígitos');
        return;
      }
      const hashed = await hashPin(pin);
      const salt = generateSalt();
      setupPin(hashed, salt);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-dark">
      <Card className="w-full max-w-sm p-8 space-y-6 text-center">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">Bóveda</h1>
          <p className="text-gray-400">
            {isSetup ? 'Introduce tu PIN para acceder' : 'Configura tu PIN de acceso'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <Input 
            type="password" 
            placeholder="PIN de Seguridad" 
            value={pin}
            onChange={e => setPin(e.target.value)}
            className="text-center text-2xl tracking-widest"
            autoFocus
          />
          {error && <p className="text-red-500 text-sm">{error}</p>}
          <Button type="submit" className="w-full" size="lg">
            {isSetup ? 'Desbloquear' : 'Crear Acceso'}
          </Button>
        </form>

        <p className="text-[10px] text-gray-600 uppercase tracking-wider">
          Todo el procesamiento es local. Nunca guardamos tu PIN.
        </p>
      </Card>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useStore } from './app/store';
import { LoginPage } from './app/pages/Login';
import { NotesPage } from './app/pages/Notes';
import { ShoppingPage } from './app/pages/Shopping';
import { Button } from './shared/ui';

/**
 * Navegación simple por Hash para evitar dependencias externas complejas
 */
const App: React.FC = () => {
  const { auth, lock, settings } = useStore();
  const [activeTab, setActiveTab] = useState('notes');

  // Sistema de auto-bloqueo por inactividad
  useEffect(() => {
    let timeout: number;
    const reset = () => {
      clearTimeout(timeout);
      timeout = window.setTimeout(lock, settings.autoLockMinutes * 60000);
    };

    window.addEventListener('mousemove', reset);
    window.addEventListener('keypress', reset);
    reset();

    return () => {
      window.removeEventListener('mousemove', reset);
      window.removeEventListener('keypress', reset);
      clearTimeout(timeout);
    };
  }, [lock, settings.autoLockMinutes]);

  if (auth.isLocked) {
    return <LoginPage />;
  }

  return (
    <div className={`min-h-screen flex flex-col ${settings.seniorMode ? 'senior-mode' : ''}`}>
      {/* Header */}
      <header className="bg-dark-surface border-b border-dark-border p-4 flex justify-between items-center sticky top-0 z-30">
        <h1 className="text-xl font-bold bg-gradient-to-r from-blue-500 to-indigo-500 bg-clip-text text-transparent">
          Bóveda Personal
        </h1>
        <div className="flex gap-2">
          <Button variant="ghost" onClick={lock} size="sm">Bloquear</Button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full">
        {activeTab === 'notes' && <NotesPage />}
        {activeTab === 'shopping' && <ShoppingPage />}
        {activeTab === 'settings' && (
          <div className="max-w-md mx-auto space-y-8">
            <h2 className="text-2xl font-bold">Ajustes</h2>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-4 bg-dark-surface rounded-xl border border-dark-border">
                <span>Modo Senior (Textos grandes)</span>
                <input 
                  type="checkbox" 
                  checked={settings.seniorMode}
                  onChange={e => useStore.getState().setSeniorMode(e.target.checked)}
                />
              </div>
              <div className="p-4 bg-dark-surface rounded-xl border border-dark-border space-y-4">
                <h3 className="font-semibold">Backup</h3>
                <p className="text-xs text-gray-500">Exporta todos tus datos localmente en formato JSON.</p>
                <Button className="w-full" variant="secondary">Exportar Datos</Button>
              </div>
            </div>
          </div>
        )}
      </main>

