    const data = {
      notes: await db.notes.toArray(),
      documents: await db.documents.toArray(),
      shopping: await db.shoppingList.toArray(),
      appointments: await db.appointments.toArray(),
      exportedAt: Date.now()
    };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `boveda_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleRepair = async () => {
    if (confirm("Se limpiará la caché y se reiniciará el Service Worker. ¿Continuar?")) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      for (let registration of registrations) {
        await registration.unregister();
      }
      const cacheNames = await caches.keys();
      for (let name of cacheNames) {
        await caches.delete(name);
      }
      window.location.reload();
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8">
      <h2 className="text-2xl font-bold">Ajustes del Sistema</h2>

