          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <Button variant="secondary" onClick={handleExport}>Exportar Backup JSON</Button>
            <Button variant="secondary" onClick={() => alert("Función de importación: Seleccione el archivo JSON generado anteriormente.")}>Importar Backup</Button>
          </div>
        </Card>
      </section>

      <section className="space-y-4">
        <h3 className="text-sm font-semibold text-gray-500 uppercase">Mantenimiento</h3>
        <Button variant="danger" className="w-full" onClick={handleRepair}>Reparar Aplicación (Limpiar Caché)</Button>
        <p className="text-[10px] text-center text-gray-600">Versión 1.0.0 - Bóveda Local Estricta</p>
