  isLocked: boolean;   // ¿Está la bóveda bloqueada?
  salt?: string;       // Salt aleatorio para PBKDF2
  canary?: string;     // Texto fijo cifrado para validar el PIN
  failedAttempts: number;
  lockUntil?: number;  // Timestamp para bloqueo por fuerza bruta
}

/**
 * Implementación de Criptografía de Máxima Seguridad (Local-only)
 * Algoritmos: AES-GCM (256-bit) + PBKDF2 (SHA-256)
 */

const CANARY_TEXT = "BOVEDA_AUTH_OK";
const AES_ALGO = "AES-GCM";
const KDF_ALGO = "PBKDF2";

/**
 * Genera un salt aleatorio para la instalación
 */
export const generateSalt = () => {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return btoa(String.fromCharCode(...salt));
};

/**
 * Deriva una CryptoKey a partir del PIN del usuario
 */
export async function deriveKey(pin: string, saltStr: string, iterations: number): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const salt = Uint8Array.from(atob(saltStr), c => c.charCodeAt(0));

  const baseKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(pin),
    KDF_ALGO,
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    {
      name: KDF_ALGO,
      salt: salt,
      iterations: iterations,
      hash: "SHA-256",
    },
    baseKey,
    { name: AES_ALGO, length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

/**
 * Cifra un texto plano usando una CryptoKey
 */
export async function encrypt(text: string, key: CryptoKey): Promise<{ ciphertext: string; iv: string }> {
  const iv = crypto.getRandomValues(new Uint8Array(12)); // IV recomendado para GCM
  const encoded = new TextEncoder().encode(text);

  const encrypted = await crypto.subtle.encrypt(
    { name: AES_ALGO, iv },
    key,
    encoded
  );

  return {
    ciphertext: btoa(String.fromCharCode(...new Uint8Array(encrypted))),
    iv: btoa(String.fromCharCode(...iv))
  };
}

/**
 * Descifra un ciphertext usando una CryptoKey
 */
export async function decrypt(ciphertext: string, ivStr: string, key: CryptoKey): Promise<string> {
  try {
    const iv = Uint8Array.from(atob(ivStr), c => c.charCodeAt(0));
    const data = Uint8Array.from(atob(ciphertext), c => c.charCodeAt(0));

    const decrypted = await crypto.subtle.decrypt(
      { name: AES_ALGO, iv },
      key,
      data
    );

    return new TextDecoder().decode(decrypted);
  } catch (e) {
    throw new Error("Fallo al descifrar: Datos corruptos o clave inválida");
  }
}

/**
 * Crea un "canario" cifrado para verificar el PIN en el futuro
 */
export async function createCanary(key: CryptoKey): Promise<string> {
  const result = await encrypt(CANARY_TEXT, key);
  return JSON.stringify(result); // Guardamos ciphertext + iv
}

/**
 * Verifica si una clave es válida intentando descifrar el canario
 */
export async function verifyKey(key: CryptoKey, canaryJson: string): Promise<boolean> {
  try {
    const { ciphertext, iv } = JSON.parse(canaryJson);
    const decrypted = await decrypt(ciphertext, iv, key);
    return decrypted === CANARY_TEXT;
  } catch {
    return false;
  }
}

import { create } from 'zustand';
import { AppSettings, AuthState } from '../domain/types';

interface GlobalState {
  settings: AppSettings;
  auth: AuthState;
  sessionKey: CryptoKey | null; // NUNCA persistir esto

  setSeniorMode: (enabled: boolean) => void;
  setAutoLock: (minutes: number) => void;

  // Acciones de Seguridad
  setSessionKey: (key: CryptoKey | null) => void;
  registerFailure: () => void;
  resetFailures: () => void;
  lock: () => void;
  setupBoveda: (salt: string, canary: string) => void;
  wipeAll: () => void;
}

const STORAGE_KEYS = {
  SETTINGS: 'boveda_v2_settings',
  SALT: 'boveda_v2_salt',
  CANARY: 'boveda_v2_canary',
  FAILURES: 'boveda_v2_failures',
  LOCK_UNTIL: 'boveda_v2_lock_until'
};

const getInitialSettings = (): AppSettings => {
  const saved = localStorage.getItem(STORAGE_KEYS.SETTINGS);
  return saved ? JSON.parse(saved) : {
    seniorMode: false,
    autoLockMinutes: 5,
    iterations: 250000
  };
};

const getInitialAuth = (): AuthState => {
  const salt = localStorage.getItem(STORAGE_KEYS.SALT);
  const lockUntil = Number(localStorage.getItem(STORAGE_KEYS.LOCK_UNTIL)) || 0;
  return {
    isSetup: !!salt,
    isLocked: true,
    salt: salt || undefined,
    canary: localStorage.getItem(STORAGE_KEYS.CANARY) || undefined,
    failedAttempts: Number(localStorage.getItem(STORAGE_KEYS.FAILURES)) || 0,
    lockUntil: lockUntil > Date.now() ? lockUntil : undefined
  };
};

export const useStore = create<GlobalState>((set) => ({
  settings: getInitialSettings(),
  auth: getInitialAuth(),
  sessionKey: null,

  setSeniorMode: (seniorMode) => set((state) => {
    const newSettings = { ...state.settings, seniorMode };
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(newSettings));
    return { settings: newSettings };
  }),

  setAutoLock: (autoLockMinutes) => set((state) => {
    const newSettings = { ...state.settings, autoLockMinutes };
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(newSettings));
    return { settings: newSettings };
  }),

  setSessionKey: (key) => set((state) => ({ 
    sessionKey: key, 
    auth: { ...state.auth, isLocked: !key } 
  })),

  registerFailure: () => set((state) => {
    const nextAttempts = state.auth.failedAttempts + 1;
    let lockUntil = undefined;

    // Backoff exponencial tras 3 intentos
    if (nextAttempts >= 3) {
      const waitTime = Math.pow(2, nextAttempts - 3) * 1000 * 30; // 30s, 60s, 120s...
      lockUntil = Date.now() + Math.min(waitTime, 3600000); // Máx 1 hora
      localStorage.setItem(STORAGE_KEYS.LOCK_UNTIL, lockUntil.toString());
    }

    localStorage.setItem(STORAGE_KEYS.FAILURES, nextAttempts.toString());
    return { 
      auth: { ...state.auth, failedAttempts: nextAttempts, lockUntil } 
    };
  }),

  resetFailures: () => set((state) => {
    localStorage.removeItem(STORAGE_KEYS.FAILURES);
    localStorage.removeItem(STORAGE_KEYS.LOCK_UNTIL);
    return { auth: { ...state.auth, failedAttempts: 0, lockUntil: undefined } };
  }),

  lock: () => set((state) => ({ 
    sessionKey: null, 
    auth: { ...state.auth, isLocked: true } 
  })),

  setupBoveda: (salt, canary) => {
    localStorage.setItem(STORAGE_KEYS.SALT, salt);
    localStorage.setItem(STORAGE_KEYS.CANARY, canary);
    set((state) => ({
      auth: { ...state.auth, isSetup: true, salt, canary, isLocked: true }
    }));
  },

  wipeAll: () => {
    Object.values(STORAGE_KEYS).forEach(k => localStorage.removeItem(k));
    indexedDB.deleteDatabase('BovedaPersonalDB');
    window.location.reload();
  }
}));

import React, { useState, useEffect } from 'react';
import { useStore } from '../store';
import { deriveKey, generateSalt, createCanary, verifyKey } from '../../shared/crypto';
import { Button, Input, Card } from '../../shared/ui';

export const LoginPage: React.FC = () => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { auth, settings, setSessionKey, setupBoveda, registerFailure, resetFailures, wipeAll } = useStore();

  const isLockedBySystem = auth.lockUntil && auth.lockUntil > Date.now();
  const [timeLeft, setTimeLeft] = useState(0);

  useEffect(() => {
    if (!isLockedBySystem) return;
    const interval = setInterval(() => {
      const diff = Math.ceil((auth.lockUntil! - Date.now()) / 1000);
      if (diff <= 0) {
        setTimeLeft(0);
        clearInterval(interval);
      } else {
        setTimeLeft(diff);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [isLockedBySystem, auth.lockUntil]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLockedBySystem || loading) return;
    setLoading(true);
    setError('');

    try {
      const derived = await deriveKey(pin, auth.salt!, settings.iterations);
      const isValid = await verifyKey(derived, auth.canary!);

      if (isValid) {
        resetFailures();
        setSessionKey(derived);
      } else {
        registerFailure();
        setError('PIN de acceso incorrecto');
        setPin('');
      }
    } catch (err) {
      setError('Error en el proceso de descifrado');
    } finally {
      setLoading(false);
    }
  };

  const handleSetup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pin.length < 4) {
      setError('El PIN debe tener al menos 4 dígitos');
      return;
    }
    setLoading(true);
    try {
      const salt = generateSalt();
      const key = await deriveKey(pin, salt, settings.iterations);
      const canary = await createCanary(key);
      setupBoveda(salt, canary);
      setPin('');
      setError('Bóveda configurada. Inicie sesión.');
    } catch (err) {
      setError('Error al configurar la seguridad');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-dark">
      <Card className="w-full max-w-sm p-8 space-y-6 text-center border-t-4 border-blue-600">
        <header>
          <div className="text-4xl mb-2">🛡️</div>
          <h1 className="text-2xl font-black text-white tracking-tighter">BÓVEDA PERSONAL</h1>
          <p className="text-xs text-gray-500 uppercase font-bold tracking-widest mt-1">
            MÁXIMA SEGURIDAD LOCAL
          </p>
        </header>

        {isLockedBySystem ? (
          <div className="p-4 bg-red-900/20 border border-red-900/50 rounded-xl">
            <p className="text-red-500 font-bold">Bóveda Bloqueada Temporalmente</p>
            <p className="text-sm text-gray-400 mt-2">Demasiados intentos fallidos.</p>
            <p className="text-2xl font-mono mt-2 text-white">{timeLeft}s</p>
          </div>
        ) : (
          <form onSubmit={auth.isSetup ? handleLogin : handleSetup} className="space-y-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-500 uppercase text-left block">
                {auth.isSetup ? 'Introduzca PIN de acceso' : 'Establecer nuevo PIN'}
              </label>
              <Input 
                type="password" 
                placeholder="••••" 
                value={pin}
                onChange={e => setPin(e.target.value.replace(/\D/g, ''))}
                className="text-center text-3xl tracking-[0.5em] font-mono"
                maxLength={8}
                disabled={loading}
                autoFocus
              />
            </div>
            {error && <p className="text-red-500 text-xs bg-red-500/10 p-2 rounded border border-red-500/20">{error}</p>}
            <Button className="w-full" size="lg" disabled={loading}>
              {loading ? 'Procesando...' : (auth.isSetup ? 'Desbloquear Bóveda' : 'Inicializar Seguridad')}
            </Button>
          </form>
        )}

        <footer className="pt-4 border-t border-dark-border space-y-4">
          <p className="text-[10px] text-gray-600 leading-relaxed italic">
            Sus datos se cifran con AES-256 en su dispositivo. 
            Si olvida su PIN, sus datos serán IRRECUPERABLES.
          </p>
          {!auth.isSetup && (
            <p className="text-[10px] text-blue-500 font-bold uppercase">
              La clave se derivará con 250,000 iteraciones PBKDF2.
            </p>
          )}
          {auth.failedAttempts > 0 && (
            <button 
              onClick={() => { if(confirm("¿BORRAR TODO? Esto destruirá permanentemente todos los datos.")) wipeAll(); }}
              className="text-[10px] text-red-700 hover:text-red-500 font-bold uppercase tracking-tighter transition-colors"
            >
              Autodestrucción / Wipe
            </button>
          )}
        </footer>
      </Card>
    </div>
  );
};

import { useCallback } from 'react';
import { useStore } from '../store';
import { encrypt, decrypt } from '../../shared/crypto';

export const useEncryption = () => {
  const { sessionKey, lock } = useStore();

  const encryptData = useCallback(async (text: string) => {
    if (!sessionKey) {
      lock();
      throw new Error("Sesión expirada");
    }
    return await encrypt(text, sessionKey);
  }, [sessionKey, lock]);

  const decryptData = useCallback(async (ciphertext: string, iv: string) => {
    if (!sessionKey) {
      lock();
      throw new Error("Sesión expirada");
    }
    return await decrypt(ciphertext, iv, sessionKey);
  }, [sessionKey, lock]);

  return { encryptData, decryptData, isReady: !!sessionKey };
};

import React from 'react';
import { useStore } from '../store';
