import { useStore } from '../store';

/**
 * Hook para gestionar operaciones criptográficas con el PIN de sesión
 */
export const useCrypto = () => {
  const [sessionPin, setSessionPin] = useState<string | null>(null);
  const { auth, settings } = useStore();

  // Fix: Re-implemented encrypt logic using correct shared/crypto functions
  const encryptData = useCallback(async (text: string) => {
    if (!sessionPin || !auth.salt) throw new Error('Sesión no autorizada');
    const key = await deriveKey(sessionPin, auth.salt, settings.iterations);
    return encrypt(text, key);
  }, [sessionPin, auth.salt, settings.iterations]);

  // Fix: Re-implemented decrypt logic using correct shared/crypto functions
  const decryptData = useCallback(async (ciphertext: string, iv: string) => {
    if (!sessionPin || !auth.salt) throw new Error('Sesión no autorizada');
    const key = await deriveKey(sessionPin, auth.salt, settings.iterations);
    return decrypt(ciphertext, iv, key);
  }, [sessionPin, auth.salt, settings.iterations]);

  return { setSessionPin, encrypt: encryptData, decrypt: decryptData, hasSession: !!sessionPin };
};

