import { Note } from '../../domain/types';
import { Button, Card, Input, Modal } from '../../shared/ui';

export const NotesPage: React.FC = () => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [newNote, setNewNote] = useState({ title: '', content: '' });

  const loadNotes = async () => setNotes(await NoteRepository.getAll());
  useEffect(() => { loadNotes(); }, []);

  const handleSpeech = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Su navegador no soporta dictado por voz.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'es-ES';
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setNewNote(prev => ({ ...prev, content: prev.content + " " + transcript }));
    };
    recognition.start();
  };

  const handleGPS = () => {
    navigator.geolocation.getCurrentPosition((pos) => {
      const { latitude, longitude } = pos.coords;
      const link = `https://www.google.com/maps?q=${latitude},${longitude}`;
      setNewNote(prev => ({ 
        ...prev, 
        content: prev.content + `\n\n📍 Ubicación guardada: ${link}` 
      }));
    }, () => alert("Error al obtener ubicación"));
  };

  const handleSave = async () => {
    if (!newNote.title.trim()) return;
    // Fix: Removed 'isEncrypted' property which is not defined in the Note interface (line 49 error)
    await NoteRepository.add({
      id: crypto.randomUUID(),
      ...newNote,
      tags: [], isFavorite: false,
      createdAt: Date.now(), updatedAt: Date.now()
    });
    setNewNote({ title: '', content: '' });
    setIsModalOpen(false);
    loadNotes();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Notas Privadas</h2>
        <Button onClick={() => setIsModalOpen(true)}>Nueva Nota</Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {notes.map(note => (
          <Card key={note.id} className="relative">
            <h3 className="font-bold text-lg mb-2">{note.title}</h3>
            <p className="text-sm text-gray-400 whitespace-pre-wrap">{note.content}</p>
            <Button variant="ghost" size="sm" className="mt-4" onClick={async () => { await NoteRepository.delete(note.id); loadNotes(); }}>Eliminar</Button>
          </Card>
        ))}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Crear Nota">
        <div className="space-y-4">
          <Input placeholder="Título" value={newNote.title} onChange={e => setNewNote({...newNote, title: e.target.value})} />
          <div className="relative">
            <textarea 
              className="w-full h-40 bg-dark-surface border border-dark-border rounded-lg p-3 text-white"
              placeholder="Escribe o dicta algo..."
              value={newNote.content}
              onChange={e => setNewNote({...newNote, content: e.target.value})}
            />
            <div className="absolute bottom-3 right-3 flex gap-2">
              <button onClick={handleSpeech} className={`p-2 rounded-full ${isListening ? 'bg-red-500 animate-pulse' : 'bg-blue-600'}`}>🎤</button>
              <button onClick={handleGPS} className="p-2 rounded-full bg-green-600">📍</button>
            </div>
          </div>
          <Button className="w-full" onClick={handleSave}>Guardar</Button>
        </div>
      </Modal>
    </div>
  );
};

export type ID = string;

export interface EncryptedData {
  ciphertext: string; // Base64
  iv: string;         // Base64
}

/**
 * Entidades cifradas: Los campos sensibles son de tipo EncryptedData
 */
export interface Note {
  id: ID;
  title: EncryptedData;
  content: EncryptedData;
  tags: EncryptedData; // Lista de etiquetas serializada y cifrada
  isFavorite: boolean;
  createdAt: number;
  updatedAt: number;
}

export interface Document {
  id: ID;
  name: EncryptedData;
  content: EncryptedData; // Base64 del archivo o texto largo
  category: EncryptedData;
  type: 'text' | 'file';
  createdAt: number;
}

export interface ShoppingItem {
  id: ID;
  text: EncryptedData;
  completed: boolean;
  createdAt: number;
}

export interface Appointment {
  id: ID;
  title: EncryptedData;
  date: string; // ISO string (necesario para ordenación sin descifrar)
  description: EncryptedData;
  createdAt: number;
}

export interface SecurityConfig {
  salt: string;
  iterations: number;
  encryptedDEK: EncryptedData; // La Clave Maestra cifrada con el PIN
  canary: EncryptedData;       // Verificador "BOVEDA_OK" cifrado con la DEK
}

export interface AppSettings {
  seniorMode: boolean;
  autoLockMinutes: number;
  readOnlyMode: boolean;
}

/**
 * Utilidades Criptográficas Ultra Seguras
 * Basado en AES-GCM (256-bit) y PBKDF2
 */

const AES_GCM = "AES-GCM";
const PBKDF2 = "PBKDF2";
const CANARY_SECRET = "BOVEDA_OK_V3";

// Auxiliares de conversión
const buf2base64 = (buf: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(buf)));
const base642buf = (base64: string) => Uint8Array.from(atob(base64), c => c.charCodeAt(0));

/**
 * Deriva una clave (KEK) a partir del PIN
 */
export async function deriveKEK(pin: string, salt: string, iterations: number): Promise<CryptoKey> {
  const encoder = new TextEncoder();
  const baseKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(pin),
    PBKDF2,
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    {
      name: PBKDF2,
      salt: base642buf(salt),
      iterations,
      hash: "SHA-256",
    },
    baseKey,
    { name: AES_GCM, length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

/**
 * Cifra datos con una clave dada
 */
export async function encryptRaw(data: string, key: CryptoKey): Promise<{ ciphertext: string; iv: string }> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encoded = new TextEncoder().encode(data);
  const encrypted = await crypto.subtle.encrypt({ name: AES_GCM, iv }, key, encoded);

  return {
    ciphertext: buf2base64(encrypted),
    iv: buf2base64(iv)
  };
}

/**
 * Descifra datos con una clave dada
 */
export async function decryptRaw(ciphertext: string, iv: string, key: CryptoKey): Promise<string> {
  const decrypted = await crypto.subtle.decrypt(
    { name: AES_GCM, iv: base642buf(iv) },
    key,
    base642buf(ciphertext)
  );
  return new TextDecoder().decode(decrypted);
}

/**
 * Genera una nueva Clave Maestra (DEK)
 */
export async function generateDEK(): Promise<CryptoKey> {
  return crypto.subtle.generateKey({ name: AES_GCM, length: 256 }, true, ["encrypt", "decrypt"]);
}

/**
 * Serializa una CryptoKey a Raw para cifrarla (Key Wrapping manual para soporte amplio)
 */
export async function wrapDEK(dek: CryptoKey, kek: CryptoKey) {
  const exported = await crypto.subtle.exportKey("raw", dek);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt({ name: AES_GCM, iv }, kek, exported);

  return {
    ciphertext: buf2base64(encrypted),
    iv: buf2base64(iv)
  };
}

export async function unwrapDEK(wrapped: { ciphertext: string; iv: string }, kek: CryptoKey): Promise<CryptoKey> {
  const decrypted = await crypto.subtle.decrypt(
    { name: AES_GCM, iv: base642buf(wrapped.iv) },
    kek,
    base642buf(wrapped.ciphertext)
  );
  return crypto.subtle.importKey("raw", decrypted, AES_GCM, true, ["encrypt", "decrypt"]);
}

/**
 * Crea el verificador (canario)
 */
export async function createCanary(dek: CryptoKey) {
  return encryptRaw(CANARY_SECRET, dek);
}

/**
 * Verifica si la clave es correcta
 */
export async function verifyDEK(dek: CryptoKey, canary: { ciphertext: string; iv: string }): Promise<boolean> {
  try {
    const val = await decryptRaw(canary.ciphertext, canary.iv, dek);
    return val === CANARY_SECRET;
  } catch {
    return false;
  }
}

import { create } from 'zustand';
import { AppSettings, SecurityConfig } from '../domain/types';

interface BovedaState {
  // Seguridad
  isSetup: boolean;
  isLocked: boolean;
  dek: CryptoKey | null; // Clave Maestra volátil
  config: SecurityConfig | null;
  failedAttempts: number;
  lockUntil: number | null;

  // Ajustes
  settings: AppSettings;

  // Acciones
  setup: (config: SecurityConfig) => void;
  unlock: (dek: CryptoKey) => void;
  lock: () => void;
  recordFailure: () => void;
  resetFailures: () => void;
  updateSettings: (s: Partial<AppSettings>) => void;
  wipe: () => void;
}

const STORAGE_KEYS = {
  CONFIG: 'bv_sec_cfg',
  SETTINGS: 'bv_settings',
  FAILURES: 'bv_fail_count',
  LOCK_TIME: 'bv_lock_until'
};

export const useStore = create<BovedaState>((set, get) => ({
  isSetup: !!localStorage.getItem(STORAGE_KEYS.CONFIG),
  isLocked: true,
  dek: null,
  config: JSON.parse(localStorage.getItem(STORAGE_KEYS.CONFIG) || 'null'),
  failedAttempts: Number(localStorage.getItem(STORAGE_KEYS.FAILURES) || '0'),
  lockUntil: Number(localStorage.getItem(STORAGE_KEYS.LOCK_TIME) || '0') || null,

  settings: JSON.parse(localStorage.getItem(STORAGE_KEYS.SETTINGS) || 'null') || {
    seniorMode: false,
    autoLockMinutes: 5,
    readOnlyMode: false
  },

  setup: (config) => {
    localStorage.setItem(STORAGE_KEYS.CONFIG, JSON.stringify(config));
    set({ config, isSetup: true, isLocked: true });
  },

  unlock: (dek) => set({ dek, isLocked: false, failedAttempts: 0, lockUntil: null }),

  lock: () => {
    // Limpieza de clave en memoria (mejor esfuerzo de GC)
    set({ dek: null, isLocked: true });
  },

  recordFailure: () => {
    const next = get().failedAttempts + 1;
    let lockUntil = null;
    if (next >= 3) {
      const wait = Math.pow(2, next - 3) * 30 * 1000; // 30s, 60s, 120s...
      lockUntil = Date.now() + wait;
      localStorage.setItem(STORAGE_KEYS.LOCK_TIME, lockUntil.toString());
    }
    localStorage.setItem(STORAGE_KEYS.FAILURES, next.toString());
    set({ failedAttempts: next, lockUntil });
  },

  resetFailures: () => {
    localStorage.removeItem(STORAGE_KEYS.FAILURES);
    localStorage.removeItem(STORAGE_KEYS.LOCK_TIME);
    set({ failedAttempts: 0, lockUntil: null });
  },

  updateSettings: (newSettings) => set((state) => {
    const settings = { ...state.settings, ...newSettings };
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
    return { settings };
  }),

  wipe: () => {
    Object.values(STORAGE_KEYS).forEach(k => localStorage.removeItem(k));
    indexedDB.deleteDatabase('BovedaPersonalDB');
    window.location.reload();
  }
}));

import { useCallback } from 'react';
import { useStore } from '../store';
import { encryptRaw, decryptRaw } from '../../shared/crypto';
import { EncryptedData } from '../../domain/types';

export const useSecurity = () => {
  const { dek, lock } = useStore();

  const encrypt = useCallback(async (text: string): Promise<EncryptedData> => {
    if (!dek) {
      lock();
      throw new Error("Sesión no válida");
    }
    return await encryptRaw(text, dek);
  }, [dek, lock]);

  const decrypt = useCallback(async (data: EncryptedData): Promise<string> => {
    if (!dek) {
      lock();
      throw new Error("Sesión no válida");
    }
    return await decryptRaw(data.ciphertext, data.iv, dek);
  }, [dek, lock]);

  return { encrypt, decrypt, isReady: !!dek };
};

import React, { useState, useEffect } from 'react';
import { useStore } from '../store';
import { deriveKEK, generateDEK, wrapDEK, unwrapDEK, createCanary, verifyDEK } from '../../shared/crypto';
import { Button, Input, Card } from '../../shared/ui';

export const LoginPage: React.FC = () => {
  const [pin, setPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { isSetup, config, lockUntil, setup, unlock, recordFailure, wipe } = useStore();

  const isTimeLocked = lockUntil && lockUntil > Date.now();
  const [timeLeft, setTimeLeft] = useState(0);

  useEffect(() => {
    if (!isTimeLocked) return;
    const timer = setInterval(() => {
      const remaining = Math.ceil((lockUntil! - Date.now()) / 1000);
      if (remaining <= 0) setTimeLeft(0);
      else setTimeLeft(remaining);
    }, 1000);
    return () => clearInterval(timer);
  }, [isTimeLocked, lockUntil]);

  const handleSetup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pin.length < 4) return setError('Mínimo 4 dígitos');
    setLoading(true);
    try {
      const salt = btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16))));
      const iterations = 150000;
      const kek = await deriveKEK(pin, salt, iterations);
      const dek = await generateDEK();
      const wrappedDEK = await wrapDEK(dek, kek);
      const canary = await createCanary(dek);

      setup({ salt, iterations, encryptedDEK: wrappedDEK, canary });
      unlock(dek);
    } catch (err) {
      setError('Error crítico de cifrado');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isTimeLocked || loading) return;
    setLoading(true);
    setError('');

    try {
      const kek = await deriveKEK(pin, config!.salt, config!.iterations);
      const dek = await unwrapDEK(config!.encryptedDEK, kek);
      const isValid = await verifyDEK(dek, config!.canary);

      if (isValid) {
        unlock(dek);
      } else {
        recordFailure();
        setError('PIN Incorrecto');
        setPin('');
      }
    } catch (err) {
      recordFailure();
      setError('Error al descifrar clave maestra');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-dark flex flex-col items-center justify-center p-6">
      <Card className="w-full max-w-sm space-y-6 border-blue-600/30">
        <header className="text-center space-y-2">
          <span className="text-5xl block">🛡️</span>
          <h1 className="text-2xl font-black text-white tracking-tighter uppercase">Bóveda Personal</h1>
          <p className="text-[10px] text-gray-500 font-bold tracking-[0.2em] uppercase">Ultra Security Edition</p>
        </header>

        {isTimeLocked ? (
          <div className="bg-red-900/10 border border-red-500/30 p-4 rounded-xl text-center">
            <p className="text-red-500 font-bold">Bloqueo de seguridad</p>
            <p className="text-3xl font-mono mt-2">{timeLeft}s</p>
          </div>
        ) : (
          <form onSubmit={isSetup ? handleLogin : handleSetup} className="space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-500 uppercase ml-1">
                {isSetup ? 'Introduzca PIN' : 'Establecer nuevo PIN'}
              </label>
              <Input 
                type="password" 
                value={pin}
                onChange={e => setPin(e.target.value.replace(/\D/g, ''))}
                placeholder="••••"
                className="text-center text-3xl font-mono tracking-widest"
                maxLength={12}
                disabled={loading}
                autoFocus
              />
            </div>
            {error && <p className="text-red-500 text-xs text-center font-bold bg-red-500/10 p-2 rounded">{error}</p>}
            <Button className="w-full" size="lg" disabled={loading}>
              {loading ? 'Cifrando...' : (isSetup ? 'Desbloquear' : 'Inicializar Bóveda')}
            </Button>
          </form>
        )}

        <footer className="pt-4 border-t border-dark-border space-y-4">
          <p className="text-[9px] text-gray-600 italic leading-relaxed text-center">
            Los datos se cifran localmente con AES-GCM-256. 
            Sin PIN, los datos son IRRECUPERABLES.
          </p>
          <div className="flex justify-center">
            <button 
              onClick={() => confirm("¿Deseas borrar TODO?") && wipe()}
              className="text-[9px] text-red-900 font-bold uppercase hover:text-red-600 transition-colors"
            >
              Borrado de emergencia (Wipe)
            </button>
          </div>
        </footer>
      </Card>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { NoteRepository } from '../../infra/db';
import { Note } from '../../domain/types';
import { useSecurity } from '../hooks/useSecurity';
import { Button, Card, Input, Modal } from '../../shared/ui';

export const NotesPage: React.FC = () => {
  const [encryptedNotes, setEncryptedNotes] = useState<Note[]>([]);
  const [decryptedNotes, setDecryptedNotes] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newNote, setNewNote] = useState({ title: '', content: '' });
  const [loading, setLoading] = useState(true);

  const { encrypt, decrypt } = useSecurity();

  const load = async () => {
    setLoading(true);
    const raw = await NoteRepository.getAll();
    setEncryptedNotes(raw);

    // Descifrado masivo en memoria
    const decoded = await Promise.all(raw.map(async (n) => ({
      ...n,
      title: await decrypt(n.title),
      content: await decrypt(n.content)
    })));
    setDecryptedNotes(decoded);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const filtered = useMemo(() => {
    return decryptedNotes.filter(n => 
      n.title.toLowerCase().includes(search.toLowerCase()) || 
      n.content.toLowerCase().includes(search.toLowerCase())
    );
  }, [decryptedNotes, search]);

  const handleSave = async () => {
    if (!newNote.title.trim()) return;
    const encryptedTitle = await encrypt(newNote.title);
    const encryptedContent = await encrypt(newNote.content);
    const encryptedTags = await encrypt("[]");

    await NoteRepository.add({
      id: crypto.randomUUID(),
      title: encryptedTitle,
      content: encryptedContent,
      tags: encryptedTags,
      isFavorite: false,
      createdAt: Date.now(),
      updatedAt: Date.now()
    });

    setNewNote({ title: '', content: '' });
    setIsModalOpen(false);
    load();
  };

  const handleGPS = () => {
    navigator.geolocation.getCurrentPosition((pos) => {
      const msg = `\n\n📍 Ubicación: ${pos.coords.latitude}, ${pos.coords.longitude}\nGoogle Maps: https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`;
      setNewNote(p => ({ ...p, content: p.content + msg }));
    }, () => alert("Permiso de GPS denegado"));
  };

  const handleDictate = () => {
    const Rec = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!Rec) return alert("Navegador no compatible");
    const recognition = new Rec();
    recognition.lang = 'es-ES';
    recognition.onresult = (e: any) => {
      const text = e.results[0][0].transcript;
      setNewNote(p => ({ ...p, content: p.content + " " + text }));
    };
    recognition.start();
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col md:flex-row justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-white">Notas Privadas</h2>
          <p className="text-xs text-gray-500 uppercase font-bold tracking-widest">Contenido cifrado AES-256</p>
        </div>
        <div className="flex gap-2">
          <Input 
            placeholder="Buscar en memoria..." 
            value={search} 
            onChange={e => setSearch(e.target.value)} 
            className="md:w-64"
          />
          <Button onClick={() => setIsModalOpen(true)}>Crear</Button>
        </div>
      </header>

      {loading ? (
        <div className="text-center py-20 animate-pulse text-gray-500">Descifrando bóveda...</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map(note => (
            <Card key={note.id} className="group hover:border-blue-500/50 transition-all">
              <div className="flex justify-between items-start mb-2">
                <h3 className="font-bold text-xl text-white">{note.title}</h3>
                <span className="text-[10px] text-gray-600 font-mono">
                  {new Date(note.createdAt).toLocaleDateString()}
                </span>
              </div>
              <p className="text-sm text-gray-400 line-clamp-4 whitespace-pre-wrap">{note.content}</p>
              <footer className="mt-4 pt-4 border-t border-dark-border flex justify-end gap-2">
                <Button variant="ghost" size="sm" onClick={async () => {
                  if(confirm("¿Eliminar nota?")) {
                    await NoteRepository.delete(note.id);
                    load();
                  }
                }}>Eliminar</Button>
              </footer>
            </Card>
          ))}
          {filtered.length === 0 && !loading && (
            <div className="col-span-full py-20 text-center border-2 border-dashed border-dark-border rounded-2xl text-gray-600">
              No se encontraron resultados
            </div>
          )}
        </div>
      )}

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Nueva Nota Segura">
        <div className="space-y-4">
          <Input placeholder="Título de la nota" value={newNote.title} onChange={e => setNewNote(p => ({...p, title: e.target.value}))} />
          <div className="relative">
            <textarea 
              className="w-full h-48 bg-dark-surface border border-dark-border rounded-xl p-4 text-white resize-none focus:outline-none focus:border-blue-500 transition-colors"
              placeholder="Escriba aquí..."
              value={newNote.content}
              onChange={e => setNewNote(p => ({...p, content: e.target.value}))}
            />
            <div className="absolute bottom-4 right-4 flex gap-2">
              <button onClick={handleDictate} className="p-2 bg-blue-600/20 text-blue-500 rounded-full hover:bg-blue-600 hover:text-white transition-all" title="Dictar">🎤</button>
              <button onClick={handleGPS} className="p-2 bg-green-600/20 text-green-500 rounded-full hover:bg-green-600 hover:text-white transition-all" title="Ubicación">📍</button>
            </div>
          </div>
          <Button className="w-full" size="lg" onClick={handleSave}>Guardar en Bóveda</Button>
        </div>
      </Modal>
    </div>
  );
};

