import { useState, useCallback } from 'react';
// Fix: Import correct cryptographic functions from shared/crypto instead of non-existent members
import { decryptRaw, encryptRaw, deriveKEK } from '../../shared/crypto';
import { useStore } from '../store';

/**
 * Hook para gestionar operaciones criptográficas con el PIN de sesión
 */
export const useCrypto = () => {
  const [sessionPin, setSessionPin] = useState<string | null>(null);
  // Fix: useStore provides 'config' which contains security parameters like salt and iterations
  const { config } = useStore();

  // Fix: Re-implemented encrypt logic using correct shared/crypto functions and store state
  const encryptData = useCallback(async (text: string) => {
    if (!sessionPin || !config?.salt) throw new Error('Sesión no autorizada');
    const key = await deriveKEK(sessionPin, config.salt, config.iterations);
    return encryptRaw(text, key);
  }, [sessionPin, config]);

  // Fix: Re-implemented decrypt logic using correct shared/crypto functions and store state
  const decryptData = useCallback(async (ciphertext: string, iv: string) => {
    if (!sessionPin || !config?.salt) throw new Error('Sesión no autorizada');
    const key = await deriveKEK(sessionPin, config.salt, config.iterations);
    return decryptRaw(ciphertext, iv, key);
  }, [sessionPin, config]);

  return { setSessionPin, encrypt: encryptData, decrypt: decryptData, hasSession: !!sessionPin };
};

import { useCallback } from 'react';
import { useStore } from '../store';
// Fix: Import correct cryptographic functions from shared/crypto instead of non-existent members
import { encryptRaw, decryptRaw } from '../../shared/crypto';

export const useEncryption = () => {
  // Fix: useStore provides 'dek' (Master Key) which should be used for operations when unlocked
  const { dek, lock } = useStore();

  const encryptData = useCallback(async (text: string) => {
    if (!dek) {
      lock();
      throw new Error("Sesión expirada");
    }
    return await encryptRaw(text, dek);
  }, [dek, lock]);

  const decryptData = useCallback(async (ciphertext: string, iv: string) => {
    if (!dek) {
      lock();
      throw new Error("Sesión expirada");
    }
    return await decryptRaw(ciphertext, iv, dek);
  }, [dek, lock]);

  return { encryptData, decryptData, isReady: !!dek };
};

import React, { useState, useEffect } from 'react';
import { ShoppingRepository } from '../../infra/db';
import { ShoppingItem } from '../../domain/types';
import { Button, Card, Input } from '../../shared/ui';
import { useSecurity } from '../hooks/useSecurity';

export const ShoppingPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [newItem, setNewItem] = useState('');
  const { encrypt, decrypt } = useSecurity();

  const load = async () => {
    const raw = await ShoppingRepository.getAll();
    // Fix: Decrypt items in memory for display
    const decoded = await Promise.all(raw.map(async (item) => ({
      ...item,
      text: await decrypt(item.text)
    })));
    setItems(decoded);
  };

  useEffect(() => { load(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.trim()) return;

    // Fix: Encrypt text before saving to the database
    const encryptedText = await encrypt(newItem);

    await ShoppingRepository.add({
      id: crypto.randomUUID(),
      text: encryptedText,
      completed: false,
      createdAt: Date.now()
    });
    setNewItem('');
    load();
  };

  const handleToggle = async (id: string) => {
    await ShoppingRepository.toggle(id);
    load();
  };

  const handleDelete = async (id: string) => {
    await ShoppingRepository.delete(id);
    load();
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <h2 className="text-2xl font-bold text-white">Lista de Compras</h2>

      <form onSubmit={handleAdd} className="flex gap-2">
        <Input 
          placeholder="¿Qué necesitas comprar?" 
          value={newItem}
          onChange={e => setNewItem(e.target.value)}
        />
        <Button type="submit">Añadir</Button>
      </form>

      <div className="space-y-2">
        {items.map(item => (
          <Card key={item.id} className="flex items-center justify-between py-3">
            <div className="flex items-center gap-3">
              <input 
                type="checkbox" 
                checked={item.completed}
                onChange={() => handleToggle(item.id)}
                className="w-5 h-5 rounded border-dark-border text-blue-600 bg-dark-surface"
              />
              <span className={`${item.completed ? 'line-through text-gray-600' : 'text-gray-200'}`}>
                {item.text}
              </span>
            </div>
            <button 
              onClick={() => handleDelete(item.id)}
              className="text-gray-500 hover:text-red-500"
            >
              &times;
            </button>
          </Card>
        ))}
      </div>

      {items.length === 0 && (
        <p className="text-center text-gray-600 py-10">La lista está vacía.</p>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { DocumentRepository } from '../../infra/db';
import { Document } from '../../domain/types';
import { Button, Card, Input, Modal } from '../../shared/ui';
import { useSecurity } from '../hooks/useSecurity';

export const DocumentsPage: React.FC = () => {
  const [docs, setDocs] = useState<any[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newDoc, setNewDoc] = useState({ name: '', category: '', content: '' });
  const { encrypt, decrypt } = useSecurity();

  const load = async () => {
    const raw = await DocumentRepository.getAll();
    // Fix: Decrypt document metadata and content for display and usage
    const decoded = await Promise.all(raw.map(async (doc) => ({
      ...doc,
      name: await decrypt(doc.name),
      category: await decrypt(doc.category),
      content: await decrypt(doc.content)
    })));
    setDocs(decoded);
  };

  useEffect(() => { load(); }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      setNewDoc({ ...newDoc, name: file.name, content: event.target?.result as string });
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!newDoc.name || !newDoc.content) return;

    // Fix: Encrypt sensitive fields before saving
    const encryptedName = await encrypt(newDoc.name);
    const encryptedCategory = await encrypt(newDoc.category || 'General');
    const encryptedContent = await encrypt(newDoc.content);

    await DocumentRepository.add({
      id: crypto.randomUUID(),
      name: encryptedName,
      category: encryptedCategory,
      content: encryptedContent,
      type: newDoc.content.startsWith('data:') ? 'file' : 'text',
      createdAt: Date.now()
    });
    setNewDoc({ name: '', category: '', content: '' });
    setIsModalOpen(false);
    load();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Documentos Seguros</h2>
        <Button onClick={() => setIsModalOpen(true)}>Añadir</Button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {docs.map(doc => (
          <Card key={doc.id} className="relative group">
            <div className="text-3xl mb-2">{doc.type === 'file' ? '📄' : '📝'}</div>
            <h4 className="font-bold truncate">{doc.name}</h4>
            <p className="text-xs text-gray-500 uppercase">{doc.category}</p>
            <div className="mt-4 flex gap-2">
              <Button size="sm" variant="secondary" onClick={() => {
                const link = window.document.createElement('a');
                link.href = doc.content;
                link.download = doc.name;
                link.click();
              }}>Descargar</Button>
              <Button size="sm" variant="ghost" onClick={async () => {
                if(confirm('¿Eliminar?')) { await DocumentRepository.delete(doc.id); load(); }
              }}>Eliminar</Button>
            </div>
          </Card>
        ))}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Nuevo Documento">
        <div className="space-y-4">
          <Input placeholder="Nombre o Título" value={newDoc.name} onChange={e => setNewDoc({...newDoc, name: e.target.value})} />
          <Input placeholder="Categoría" value={newDoc.category} onChange={e => setNewDoc({...newDoc, category: e.target.value})} />
          <div className="border-2 border-dashed border-dark-border p-8 text-center rounded-xl">
            <input type="file" id="file-up" className="hidden" onChange={handleFileUpload} />
            <label htmlFor="file-up" className="cursor-pointer text-blue-500 hover:text-blue-400">
              Haga clic para subir un archivo o arrástrelo
            </label>
            {newDoc.name && <p className="mt-2 text-xs text-green-500">Seleccionado: {newDoc.name}</p>}
          </div>
          <Button className="w-full" onClick={handleSave}>Guardar en Bóveda</Button>
        </div>
      </Modal>
    </div>
  );
};

