export const SettingsPage: React.FC = () => {
  const { settings, updateSettings, config, wipe } = useStore();

  const handleExport = async () => {
    if (!config) return;

    // El backup incluye los parámetros de seguridad para que pueda ser descifrado tras importar
    const data = {
      version: "3.0-ultra-secure",
      security: {
        salt: config.salt,
        canary: config.canary,
        iterations: config.iterations,
        encryptedDEK: config.encryptedDEK
      },
      content: {
        notes: await db.notes.toArray(),
        documents: await db.documents.toArray(),
        shopping: await db.shoppingList.toArray(),
        appointments: await db.appointments.toArray(),
      },
      exportedAt: Date.now()
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `boveda_ultra_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!confirm("Esto reemplazará todos los datos actuales. ¿Desea continuar?")) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);

        if (data.version !== "3.0-ultra-secure") {
          throw new Error("Formato de backup incompatible o antiguo.");
        }

        // Limpiar DB actual
        await Promise.all([
          db.notes.clear(),
          db.documents.clear(),
          db.shoppingList.clear(),
          db.appointments.clear()
        ]);

        // Importar contenido
        await db.notes.bulkAdd(data.content.notes);
        await db.documents.bulkAdd(data.content.documents);
        await db.shoppingList.bulkAdd(data.content.shopping);
        await db.appointments.bulkAdd(data.content.appointments);

        // Actualizar parámetros de seguridad locales
        localStorage.setItem('bv_sec_cfg', JSON.stringify(data.security));

        alert("Importación completada con éxito. La aplicación se reiniciará.");
        window.location.reload();
      } catch (err: any) {
        alert("Error al importar: " + err.message);
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8">
      <header className="flex items-center gap-4">
        <div className="text-3xl">⚙️</div>
        <div>
          <h2 className="text-2xl font-bold text-white">Ajustes</h2>
          <p className="text-sm text-gray-500">Gestione su privacidad y almacenamiento local.</p>
        </div>
      </header>

      <section className="space-y-4">
        <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest border-b border-dark-border pb-2">Preferencias</h3>
        <Card className="space-y-4">
          <div className="flex justify-between items-center">
            <span className="font-semibold">Modo Senior</span>
            <input 
              type="checkbox" 
              checked={settings.seniorMode} 
              onChange={e => updateSettings({ seniorMode: e.target.checked })}
              className="w-5 h-5 accent-blue-600"
            />
          </div>
          <div className="flex justify-between items-center">
            <span className="font-semibold">Bloqueo automático</span>
            <select 
              className="bg-dark border border-dark-border rounded px-2 py-1 text-sm text-white"
              value={settings.autoLockMinutes}
              onChange={e => updateSettings({ autoLockMinutes: Number(e.target.value) })}
            >
              <option value={1}>1 minuto</option>
              <option value={5}>5 minutos</option>
              <option value={10}>10 minutos</option>
              <option value={30}>30 minutos</option>
            </select>
          </div>
        </Card>
      </section>

      <section className="space-y-4">
        <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest border-b border-dark-border pb-2">Datos y Respaldo</h3>
        <Card className="space-y-4">
          <p className="text-xs text-gray-400">
            Los backups son archivos JSON que contienen sus datos cifrados. 
            Necesitará su PIN para acceder a ellos tras una importación.
          </p>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <Button variant="secondary" onClick={handleExport} className="w-full">
              Exportar Backup
            </Button>
            <div className="relative">
              <Button variant="secondary" className="w-full">Importar Backup</Button>
              <input 
                type="file" 
                accept=".json" 
                onChange={handleImport}
                className="absolute inset-0 opacity-0 cursor-pointer"
              />
            </div>
          </div>
        </Card>
      </section>

      <section className="space-y-4 pt-8">
        <h3 className="text-xs font-black text-red-900 uppercase tracking-widest border-b border-red-900/30 pb-2">Zona Peligrosa</h3>
        <Card className="border-red-900/20 bg-red-900/5 space-y-4">
          <p className="text-xs text-red-500/80 font-bold">
            La autodestrucción eliminará irreversiblemente todos los registros, 
            el PIN de acceso y los ajustes del navegador.
          </p>
          <Button variant="danger" className="w-full" onClick={() => { if(confirm("¿BORRAR TODO? Acción irreversible.")) wipe(); }}>
            Autodestrucción de Bóveda (Wipe)
          </Button>
        </Card>
      </section>

      <footer className="text-center opacity-30 text-[10px] font-mono py-10">
        BOVEDA ULTRA SECURE V3.0 // LOCAL-ONLY
      </footer>
    </div>
  );
};

