import Dexie, { type Table } from 'dexie';
import { Note, Document, ShoppingItem, Appointment, Collection, LogEvent, Template } from '../domain/types';

export class BovedaDB extends Dexie {
  notes!: Table<Note>;
  documents!: Table<Document>;
  shoppingList!: Table<ShoppingItem>;
  appointments!: Table<Appointment>;
  collections!: Table<Collection>;
  logs!: Table<LogEvent>;
  templates!: Table<Template>;

  constructor() {
    super('BovedaPersonalDB');
    // Fix: Access the inherited 'version' method from Dexie using a type assertion to satisfy the TypeScript compiler
    (this as any).version(2).stores({
      notes: 'id, collectionId, title, isFavorite, createdAt',
      documents: 'id, collectionId, name, category, createdAt',
      shoppingList: 'id, completed, createdAt',
      appointments: 'id, date, createdAt',
      collections: 'id, name, createdAt',
      logs: 'id, timestamp',
      templates: 'id, name'
    });
  }
}

export const db = new BovedaDB();

// Sistema de registro automático
export const Logger = {
  log: async (action: string, details: string) => {
    const id = crypto.randomUUID();
    await db.logs.add({ id, action, details, timestamp: Date.now() });
    // Mantener solo los últimos 20
    const count = await db.logs.count();
    if (count > 20) {
      const oldest = await db.logs.orderBy('timestamp').first();
      if (oldest) await db.logs.delete(oldest.id);
    }
  },
  getRecent: () => db.logs.orderBy('timestamp').reverse().toArray()
};

