const App: React.FC = () => {
  const { isLocked, lock, settings, wipe } = useStore();
  const [activeTab, setActiveTab] = useState('notes');

  useEffect(() => {
    TemplateRepository.seed();
    let timeout: number;
    const reset = () => {
      clearTimeout(timeout);
      if (!isLocked) {
        timeout = window.setTimeout(lock, settings.autoLockMinutes * 60000);
      }
    };
    const events = ['mousedown', 'keydown', 'touchstart'];
    events.forEach(e => window.addEventListener(e, reset));
    reset();
    return () => {
      events.forEach(e => window.removeEventListener(e, reset));
      clearTimeout(timeout);
    };
  }, [lock, settings.autoLockMinutes, isLocked]);

  if (isLocked) return <LoginPage />;

  return (
    <div className={`min-h-screen flex flex-col bg-dark text-gray-200 ${settings.seniorMode ? 'senior-mode' : ''}`}>
