        {activeTab === 'docs' && <DocumentsPage />}
        {activeTab === 'shopping' && <ShoppingPage />}
        {activeTab === 'apps' && <AppointmentsPage />}
        {activeTab === 'activity' && <ActivityPage />}
        {activeTab === 'settings' && <SettingsPage />}
