import React, { useState, useEffect } from 'react';
import { useStore } from './app/store';
import { LoginPage } from './app/pages/Login';
import { IntroPage } from './app/pages/Intro';
import { NotesPage } from './app/pages/Notes';
import { ShoppingPage } from './app/pages/Shopping';
import { DocumentsPage } from './app/pages/Documents';
import { AppointmentsPage } from './app/pages/Appointments';
import { SettingsPage } from './app/pages/Settings';
import { ActivityPage } from './app/pages/Activity';
import { Button } from './shared/ui';
import { TemplateRepository } from './infra/db';

const App: React.FC = () => {
  const { isLocked, lock, settings, wipe } = useStore();
  const [activeTab, setActiveTab] = useState('notes');

  // Lógica de visualización de Intro
  const [showIntro, setShowIntro] = useState(() => {
    return localStorage.getItem("bp_seen_intro_v1") !== "1";
  });

  useEffect(() => {
    TemplateRepository.seed();
    let timeout: number;
    const reset = () => {
      clearTimeout(timeout);
      if (!isLocked && !showIntro) {
        timeout = window.setTimeout(lock, settings.autoLockMinutes * 60000);
      }
    };
    const events = ['mousedown', 'keydown', 'touchstart'];
    events.forEach(e => window.addEventListener(e, reset));
    reset();
    return () => {
      events.forEach(e => window.removeEventListener(e, reset));
      clearTimeout(timeout);
    };
  }, [lock, settings.autoLockMinutes, isLocked, showIntro]);

  // Pantalla de Presentación (Solo se muestra una vez)
  if (showIntro) {
    return <IntroPage onComplete={() => setShowIntro(false)} />;
  }

  // Pantalla de Bloqueo
  if (isLocked) {
    return <LoginPage />;
  }

  // Aplicación Principal
  return (
    <div className={`min-h-screen flex flex-col bg-dark text-gray-200 ${settings.seniorMode ? 'senior-mode' : ''}`}>
      <header className="bg-dark-surface border-b border-dark-border p-4 flex justify-between items-center sticky top-0 z-50 no-print">
        <h1 className="text-xl font-black text-blue-500 tracking-tighter uppercase italic">BÓVEDA</h1>
        <div className="flex gap-2">
          {settings.panicModeEnabled && (
            <button 
              onClick={() => confirm("¿EJECUTAR MODO PÁNICO? Esto borrará TODO.") && wipe()}
              className="bg-red-600 text-white px-3 py-1 rounded-lg text-xs font-black uppercase animate-pulse"
            >
              🔥 PÁNICO
            </button>
          )}
          <Button variant="ghost" size="sm" onClick={lock}>🔒 Bloquear</Button>
        </div>
      </header>

      <main className="flex-grow p-4 md:p-8 pb-24 max-w-7xl mx-auto w-full">
        {activeTab === 'notes' && <NotesPage />}
        {activeTab === 'docs' && <DocumentsPage />}
        {activeTab === 'shopping' && <ShoppingPage />}
        {activeTab === 'apps' && <AppointmentsPage />}
        {activeTab === 'activity' && <ActivityPage />}
        {activeTab === 'settings' && <SettingsPage />}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-dark-surface/80 backdrop-blur-md border-t border-dark-border p-2 flex justify-around items-center z-50 no-print">
        <NavBtn act={activeTab === 'notes'} onClick={() => setActiveTab('notes')} icon="📝" label="Notas" />
        <NavBtn act={activeTab === 'docs'} onClick={() => setActiveTab('docs')} icon="📁" label="Docs" />
        <NavBtn act={activeTab === 'shopping'} onClick={() => setActiveTab('shopping')} icon="🛒" label="Lista" />
        <NavBtn act={activeTab === 'activity'} onClick={() => setActiveTab('activity')} icon="⚡" label="Logs" />
        <NavBtn act={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon="⚙️" label="Ajustes" />
      </nav>

      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; color: black !important; }
          .card { border: 1px solid #ccc !important; box-shadow: none !important; background: white !important; color: black !important; }
        }
      `}</style>
    </div>
  );
};

const NavBtn: React.FC<{ act: boolean; onClick: () => void; icon: string; label: string }> = ({ act, onClick, icon, label }) => (
  <button onClick={onClick} className={`flex flex-col items-center flex-1 py-1 transition-all ${act ? 'text-blue-500 scale-110' : 'text-gray-500 opacity-60'}`}>
    <span className="text-xl">{icon}</span>
    <span className="text-[10px] font-bold uppercase">{label}</span>
  </button>
);

export default App;

